-- 飞升之路 / 英雄召唤告示板 / 战争游戏 三组自定义任务的文本中文化。
-- 任务标题、日志、描述与完成语都由服务端下发，客户端补丁改不到，因此只能在世界库改。
-- 每条按 ID 与英文原值双重守卫：已经汉化过的库重跑不会重复改写，也不会覆盖服主自行调整过的文案。
-- 保留原文里的 \n 换行转义与 $N/$n/$C/$c/$R/$r 等占位符。

START TRANSACTION;

UPDATE `quest_template` SET `LogTitle` = '飞升之路：有趣的虚灵' WHERE `ID` = 81000 AND `LogTitle` = 'Path to Ascension: Interesting Ethereals';
UPDATE `quest_template` SET `LogDescription` = '与拍卖行内的虚灵交谈。' WHERE `ID` = 81000 AND `LogDescription` = 'Speak to the Ethereals inside the Auction House.';
UPDATE `quest_template` SET `QuestDescription` = '有兴趣的虚灵已在拍卖行内定居，提供奇妙的商品和有用的服务。阿米尔·好运 是寻找失物并将其归还给你的专家。玛拉兹 是外观和幻化的宗师，从你的靴子到你的火球，无所不能。提拉希斯 经营虚灵集市，出售限量供应的专属外观物品和时光契约。与每个虚灵交谈并探索他们的商品和服务。' WHERE `ID` = 81000 AND `QuestDescription` = 'Interested Ethereals have taken up residence inside the Auction House offering fantastical goods and useful services.  Ameer Greatluck is an expert at finding all things lost and returning them to you.  Marazz is a master of appearances and transmogfication. Tranforming everything from your boots to your fireball.  Tiraxis runs the Ethereal Bazaar, offering exclusive cosmetic items with limited stock and Temporal Contracts.  Speak to each Ethereal and explore their goods and services.';
UPDATE `quest_template` SET `QuestCompletionLog` = '与 阿米尔·好运 交谈\n与 提拉希斯 交谈' WHERE `ID` = 81000 AND `QuestCompletionLog` = 'Talk to Ameer Greatluck\nTalk to Tiraxis';
UPDATE `quest_template` SET `ObjectiveText1` = '与 阿米尔·好运 交谈' WHERE `ID` = 81000 AND `ObjectiveText1` = 'Talk to Ameer Greatluck';
UPDATE `quest_template` SET `ObjectiveText2` = '与 提拉希斯 交谈' WHERE `ID` = 81000 AND `ObjectiveText2` = 'Talk to Tiraxis';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：史诗+商人' WHERE `ID` = 149176 AND `LogTitle` = 'Path to Ascension: Mythic+ Vendor';
UPDATE `quest_template` SET `LogDescription` = '在沙塔斯与 埃德里姆·天歌 交谈' WHERE `ID` = 149176 AND `LogDescription` = 'Talk to Edrim Skysong in Shattrath';
UPDATE `quest_template` SET `QuestDescription` = '埃德里姆·天歌 对你的史诗冒险非常感兴趣，可以在很多方面帮助你。他会向你提供装备、帮助你升级现有装备，并回收不需要的史诗物品以换取额外的史诗硬币。' WHERE `ID` = 149176 AND `QuestDescription` = 'Edrim Skysong is keenly interested in your Mythic Adventures, and can aid you in many ways. He''ll offer you gear, help you upgrade existing equipment, and recycle unwanted mythic items for additional Mythic Coins,';
UPDATE `quest_template` SET `QuestCompletionLog` = '在沙塔斯与 埃德里姆·天歌 交谈' WHERE `ID` = 149176 AND `QuestCompletionLog` = 'Talk to Edrim Skysong in Shattrath';
