UPDATE `quest_template` SET `LogDescription` = '前往诅咒之地。' WHERE `ID` = 149179 AND `LogDescription` = 'Make your way to the Blasted Lands.';
UPDATE `quest_template` SET `QuestDescription` = '你面对燃烧军团的时候到了。通过传送门前往诅咒之地，它位于暴风城法师区的法师塔顶。' WHERE `ID` = 149179 AND `QuestDescription` = 'Your time to confront the Burning Legion has come. Take the Portal to the Blasted Lands, located atop the Mage Tower in the Mage District of Stormwind.';
UPDATE `quest_template` SET `QuestCompletionLog` = '使用诅咒之地传送门并与守望指挥官 雷索恩·奈瑟维 交谈' WHERE `ID` = 149179 AND `QuestCompletionLog` = 'Use the Blasted Lands Portal and speak to Watch Commander Relthorn Netherwane';
