UPDATE `quest_template` SET `LogDescription` = '前往诅咒之地。' WHERE `ID` = 149180 AND `LogDescription` = 'Make your way to the Blasted Lands.';
UPDATE `quest_template` SET `QuestDescription` = '你面对燃烧军团的时候到了。通过奥格瑞玛的传送门前往诅咒之地，它位于精神谷。' WHERE `ID` = 149180 AND `QuestDescription` = 'Your time to confront the Burning Legion has come. Take the Portal in Orgrimmar to the Blasted Lands, located in The Valley of spirits.';
UPDATE `quest_template` SET `QuestCompletionLog` = '使用诅咒之地传送门并与督军 达图恩 交谈。' WHERE `ID` = 149180 AND `QuestCompletionLog` = 'Use the Blasted Lands Portal and speak toWarlord Dar''toon.';
