UPDATE `quest_template` SET `LogDescription` = '拜访 石坚·塔克，试炼守护者。' WHERE `ID` = 149181 AND `LogDescription` = 'Visit with Stony Tark, Keeper of Trials.';
UPDATE `quest_template` SET `QuestDescription` = '石坚·塔克 是伟大门槛前坚定不移的哨兵，试炼守护者和仪式大师。试炼是可自定义的游戏模式，会深刻改变你的游戏难度，并提供各种外观和装饰奖励。' WHERE `ID` = 149181 AND `QuestDescription` = 'Stony Tark stands as the unwavering sentinel at the threshold of greatness, the Keeper of Trials and Master of Ceremonies. Trials are customizable gamemodes that profoundly change the difficulty of your experience and offer a variety of vanity and cosmetic rewards.';
UPDATE `quest_template` SET `QuestCompletionLog` = '与 石坚·塔克 交谈' WHERE `ID` = 149181 AND `QuestCompletionLog` = 'Talk with Stony Tark';
