UPDATE `quest_template` SET `LogTitle` = '飞升之路：飞向天空！' WHERE `ID` = 149183 AND `LogTitle` = 'Path to Ascension: Take to the skys!';
UPDATE `quest_template` SET `LogDescription` = '与影月谷的飞行训练师 奥尔罗克 交谈。' WHERE `ID` = 149183 AND `LogDescription` = 'Speak with Olrokk, the Flight Instructor, in Shadowmoon Valley.';
UPDATE `quest_template` SET `QuestDescription` = '你已在地面上证明了自己的实力，但外域的天空在等待着你。如果你想在其破碎的土地上翱翔，你需要适当的训练——以及一只飞行坐骑。在影月谷寻找专业的飞行训练师。他们会引导你走上飞行的道路。' WHERE `ID` = 149183 AND `QuestDescription` = 'You''ve proven your strength on the ground, but the skies of Outland await. If you wish to soar above its shattered lands, you’ll need the proper training—and a flying mount. Seek out the expert flying trainer in Shadowmoon Valley. They''ll guide you on the path to taking flight.';
UPDATE `quest_template` SET `QuestCompletionLog` = '与影月谷的 奥尔罗克 交谈。' WHERE `ID` = 149183 AND `QuestCompletionLog` = 'Speak with Olrokk in Shadowmoon Valley.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：飞向天空！' WHERE `ID` = 149184 AND `LogTitle` = 'Path to Ascension: Take to the skys!';
UPDATE `quest_template` SET `LogDescription` = '与影月谷的飞行训练师 伊尔莎·雷酿 交谈。' WHERE `ID` = 149184 AND `LogDescription` = 'Speak with IIsa Thunderbrew, the Flight Instructor, in Shadowmoon Valley.';
UPDATE `quest_template` SET `QuestDescription` = '你已在地面上证明了自己的实力，但外域的天空在等待着你。如果你想在其破碎的土地上翱翔，你需要适当的训练——以及一只飞行坐骑。在影月谷寻找专业的飞行训练师。他们会引导你走上飞行的道路。' WHERE `ID` = 149184 AND `QuestDescription` = 'You''ve proven your strength on the ground, but the skies of Outland await. If you wish to soar above its shattered lands, you’ll need the proper training—and a flying mount. Seek out the expert flying trainer in Shadowmoon Valley. They''ll guide you on the path to taking flight.';
UPDATE `quest_template` SET `QuestCompletionLog` = '与影月谷的飞行训练师 伊尔莎·雷酿 交谈。' WHERE `ID` = 149184 AND `QuestCompletionLog` = 'Speak with IIsa Thunderbrew, the Flight Instructor, in Shadowmoon Valley.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：神秘附魔品质' WHERE `ID` = 149185 AND `LogTitle` = 'Path to Ascension: Mystic Enchantment Quality';
UPDATE `quest_template` SET `LogDescription` = '将每种品质的各 1 个附魔加入你的收藏。' WHERE `ID` = 149185 AND `LogDescription` = 'Add 1 enchant of each quality to your collection.';
UPDATE `quest_template` SET `QuestDescription` = '神秘附魔按品质划分：稀有、史诗、传说和神器。这些附魔会增强法术、改变技能，或根据其品质以不同方式提升属性。' WHERE `ID` = 149185 AND `QuestDescription` = 'Mystic Enchants are separated by quality; Rare, Epic, Legendary, and Artifact. These enchants will enhance spells, change abilities, or improve stats in different ways depending on their quality.';
UPDATE `quest_template` SET `QuestCompletionLog` = '收集每种品质的神秘附魔：稀有、史诗和传说。' WHERE `ID` = 149185 AND `QuestCompletionLog` = 'Collect a Mystic Enchant of each quality; Rare, Epic, and Legendary.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：满载' WHERE `ID` = 149186 AND `LogTitle` = 'Path to Ascension: Fully Loaded';
UPDATE `quest_template` SET `LogDescription` = '填满激活附魔界面中每一个空置的神秘附魔槽位。' WHERE `ID` = 149186 AND `LogDescription` = 'Fill every open Mystic Enchant slot in the Active Enchants UI.';
UPDATE `quest_template` SET `QuestDescription` = '神秘附魔是最大化你角色潜力的关键。因此你会想要确保已将收藏中所有可用的附魔都应用到你的激活附魔上。在单个专精中，你最多可以激活 11 个神秘附魔；6 个稀有、3 个史诗、1 个传说和 1 个神器。' WHERE `ID` = 149186 AND `QuestDescription` = 'Mystic Enchants are your key to maximizing the potential of your character. You will therefor want to make certain that you''ve applied all of the enchants that you can from your collection to your active enchants. You can activates a total of 11 Mystic Enchants in a single specialization; 6 Rare, 3 Epic, 1 Legendary, and 1 Artifact.';
UPDATE `quest_template` SET `QuestCompletionLog` = '用适当品质的附魔填满每一个激活槽位。' WHERE `ID` = 149186 AND `QuestCompletionLog` = 'Fill every active slot with an enchantment of the appropriate quality.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：激活神秘卷轴' WHERE `ID` = 149187 AND `LogTitle` = 'Path to Ascension: Activating Mystic Scrolls';
UPDATE `quest_template` SET `LogDescription` = '- 通过击败敌人或与其他玩家交易获得一个神秘附魔卷轴。  - 与你的主城中或世界中发现的神秘附魔祭坛互动，并选择附魔卷轴标签页。  - 激活一个神秘卷轴并将其应用到一个激活附魔槽位。' WHERE `ID` = 149187 AND `LogDescription` = '- Obtain a Mystic Enchanting Scroll by defeating enemies or trading other players.  - Interact with a Mystic Enchanting Altar found in your Capital City or in the World and select Enchant Scrolls tab.  - Activate a Mystic Scroll and apply it to an Active Enchant slot.';
UPDATE `quest_template` SET `QuestDescription` = '神秘附魔卷轴可以通过击败敌人、在世界各处隐藏地点发现，或与其他玩家交易获得。   一旦获得，前往神秘附魔祭坛应用神秘卷轴以获得其力量！神秘附魔祭坛经常被召唤在主城中，或者你可以前往世界中去拜访一个。它们的位置标记在世界地图上。    神秘附魔是解锁你作为英雄力量的关键。寻找能增强你法术或解锁全新原型的神秘附魔，以提升你的力量。' WHERE `ID` = 149187 AND `QuestDescription` = 'Mystic Enchanting Scrolls can be obtained by defeating enemies, found hidden throughout the world, or by trading other players.    Once obtained, visit a Mystic Enchanting Altar to apply a Mystic Scroll to gain its powers! Mystic Enchanting Altars can often be found summoned in Capital Cities, or you can venture into the world to visit one. Their locations are marked on the world map.    Mystic Enchants are key to unlocking your power as a Hero. Find Mystic Enchants that empower your spells or unlock whole new archetypes to increase your power.';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 149187 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：重铸与神秘萃取物' WHERE `ID` = 149188 AND `LogTitle` = 'Path to Ascension: Reforging and Mystic Extracts';
UPDATE `quest_template` SET `LogDescription` = '- 从神秘祭坛的附魔卷轴标签页获得一个未受玷污的神秘卷轴。  - 重铸你的神秘卷轴以获得新的神秘附魔。你可以继续重铸任何神秘卷轴，直到找到你想保留的附魔。  - 重铸神秘卷轴会为你累积通往神秘萃取物的进度。  - 重铸 5 次。继续重铸，直到你获得一个神秘萃取物。' WHERE `ID` = 149188 AND `LogDescription` = '- Obtain an Untarnished Mystic Scroll from the Enchant Scrolls tab of the Mystic Altar.  - Reforge your Mystic Scroll to obtain new Mystic Enchants. You can continue reforging any Mystic Scroll until you find an Enchant you want to keep.  - Reforging Mystic Scrolls grants you progress towards a Mystic Extract.  - Reforge 5 times. Continue Reforging until you earn a Mystic Extract.';
UPDATE `quest_template` SET `QuestDescription` = '拜访一个祭坛并选择附魔卷轴标签页，然后获得一个未受玷污的神秘卷轴。  点击神秘卷轴上的重铸会为卷轴随机生成一个新的神秘附魔，并覆盖卷轴上现有的任何附魔。重铸会消耗神秘符文，如果你没有神秘符文则消耗金币！  每次重铸你都会获得经验值，提升你的神秘附魔等级。每获得一级都会授予你一个神秘萃取物，可用于将神秘附魔永久应用到你的附魔收藏中。该收藏在服务器上的所有角色之间共享！  神秘附魔祭坛经常被召唤在主城中，或者你可以前往世界中去拜访一个。它们的位置标记在世界地图上。' WHERE `ID` = 149188 AND `QuestDescription` = 'Visit an Altar and select the Enchant Scrolls tab, then Obtain an Untarnished Mystic Scroll.  Clicking Reforge on a Mystic Scroll will roll a new Mystic Enchant on the scroll and overwrite any existing enchant on the scroll. Reforging consumes Mystic Runes, or gold if you are out of Mystic Runes!  Each time you Reforge you earn experience towards your Mystic Enchanting level. Each level earned grants you a Mystic Extract which can be used to permanently apply Mystic Enchants to your Enchant Collection. This collection is shared across all characters on the realm!  Mystic Enchanting Altars can often be found summoned in Capital Cities, or you can venture into the world to visit one. Their locations are marked on the world map.';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 149188 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：神秘附魔收藏' WHERE `ID` = 149189 AND `LogTitle` = 'Path to Ascension: Mystic Enchant Collection';
UPDATE `quest_template` SET `LogDescription` = '从神秘祭坛的卷轴标签页选择一个神秘卷轴，然后点击保存到收藏。' WHERE `ID` = 149189 AND `LogDescription` = 'Select a Mystic Scroll from the Scrolls tab in the Mystic Altar, then hit Save to Collection.';
UPDATE `quest_template` SET `QuestDescription` = '将神秘附魔保存到你的收藏会为此服务器上的所有角色永久解锁它，让你随时可以从祭坛应用该附魔，而无需卷轴！  将附魔加入你的收藏会摧毁卷轴并消耗一个神秘萃取物。你可以获得的神秘萃取物数量没有限制，所以请务必保存你最喜欢的神秘附魔以及对你构筑至关重要的附魔。  从神秘祭坛的卷轴标签页选择一个神秘卷轴，然后点击保存到收藏。' WHERE `ID` = 149189 AND `QuestDescription` = 'Saving a Mystic Enchant to your collection permanently unlocks it for all characters on this realm, allowing you to apply that enchant from an Altar whenever you want without needing a scroll!  Adding Enchants to your collection destroys the scrolls and consumes a Mystic Extract. There is no limit to how many Mystic Extracts you can acquire, so be sure to save your favorite Mystic Enchants and ones critical to your build.  Select a Mystic Scroll from the Scrolls tab in the Mystic Altar, then hit Save to Collection.';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 149189 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：使用你的神秘附魔收藏' WHERE `ID` = 189190 AND `LogTitle` = 'Path to Ascension: Using Your Mystic Enchant Collection';
UPDATE `quest_template` SET `LogDescription` = '拜访一个祭坛，并将你附魔收藏中的一个神秘附魔应用到一个激活附魔槽位。' WHERE `ID` = 189190 AND `LogDescription` = 'Visit an Altar and apply a Mystic Enchant from your Enchant Collection to an Active Enchant slot.';
UPDATE `quest_template` SET `QuestDescription` = '从神秘祭坛打开附魔收藏标签页，从你的附魔收藏中选择一个附魔并将其应用到一个激活附魔槽位，然后选择保存更改以激活你的神秘附魔。  从你的收藏中激活附魔需要神秘宝珠，可以通过召唤板上的日常任务、地下城和团队副本、战场，或在世界中击败敌人获得！  1 个传说附魔可以应用到祭坛中最大的中央槽位。  3 个史诗附魔可以应用到内环的中型槽位。  你可以在剩余槽位中应用任意数量的稀有和精良附魔。其中许多附魔最多可以叠加 3 次。将鼠标悬停在收藏中的附魔上会显示其最大叠加数。' WHERE `ID` = 189190 AND `QuestDescription` = 'Open the Enchant Collection tab from a Mystic Altar, select an Enchant from your Enchant Collections and apply it to an Active Enchant slot, then select Save Changes to activate your Mystic Enchant.  Activating Enchants from your collection requires Mystic Orbs, which can be earned from Daily Quests on the Call Board, Dungeons and Raids, Battlegrounds or defeating enemies in the world!  1 Legendary Enchant can be applied to the large center slot in the Altar.  3 Epic Enchants can be applied in the medium slots in the inner ring.  You can apply as many Rare and Uncommon Enchants in the remaining slots as you''d like. Many of these Enchants can stack up to 3 times. Mousing over the Enchant in the collection reveals its max stack size.';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 189190 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：重铸与神秘萃取物' WHERE `ID` = 580134 AND `LogTitle` = 'Path to Ascension: Reforging and Mystic Extracts';
UPDATE `quest_template` SET `LogDescription` = '- 从神秘祭坛的附魔卷轴标签页获得一个未受玷污的神秘卷轴。  - 重铸你的神秘卷轴以获得新的神秘附魔。你可以继续重铸任何神秘卷轴，直到找到你想保留的附魔。  - 重铸神秘卷轴会为你累积通往神秘萃取物的进度。  - 重铸 5 次。继续重铸，直到你获得一个神秘萃取物。' WHERE `ID` = 580134 AND `LogDescription` = '- Obtain an Untarnished Mystic Scroll from the Enchant Scrolls tab of the Mystic Altar.  - Reforge your Mystic Scroll to obtain new Mystic Enchants. You can continue reforging any Mystic Scroll until you find an Enchant you want to keep.  - Reforging Mystic Scrolls grants you progress towards a Mystic Extract.  - Reforge 5 times. Continue Reforging until you earn a Mystic Extract.';
UPDATE `quest_template` SET `QuestDescription` = '拜访一个祭坛并选择附魔卷轴标签页，然后获得一个未受玷污的神秘卷轴。  点击神秘卷轴上的重铸会为卷轴随机生成一个新的神秘附魔，并覆盖卷轴上现有的任何附魔。重铸会消耗神秘符文，如果你没有神秘符文则消耗金币！  每次重铸你都会获得经验值，提升你的神秘附魔等级。每获得一级都会授予你一个神秘萃取物，可用于将神秘附魔永久应用到你的附魔收藏中。该收藏在服务器上的所有角色之间共享！  神秘附魔祭坛经常被召唤在主城中，或者你可以前往世界中去拜访一个。它们的位置标记在世界地图上。' WHERE `ID` = 580134 AND `QuestDescription` = 'Visit an Altar and select the Enchant Scrolls tab, then Obtain an Untarnished Mystic Scroll.  Clicking Reforge on a Mystic Scroll will roll a new Mystic Enchant on the scroll and overwrite any existing enchant on the scroll. Reforging consumes Mystic Runes, or gold if you are out of Mystic Runes!  Each time you Reforge you earn experience towards your Mystic Enchanting level. Each level earned grants you a Mystic Extract which can be used to permanently apply Mystic Enchants to your Enchant Collection. This collection is shared across all characters on the realm!  Mystic Enchanting Altars can often be found summoned in Capital Cities, or you can venture into the world to visit one. Their locations are marked on the world map.';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 580134 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：神秘附魔收藏' WHERE `ID` = 580135 AND `LogTitle` = 'Path to Ascension: Mystic Enchant Collection';
UPDATE `quest_template` SET `LogDescription` = '从神秘祭坛的卷轴标签页选择一个神秘卷轴，然后点击保存到收藏。' WHERE `ID` = 580135 AND `LogDescription` = 'Select a Mystic Scroll from the Scrolls tab in the Mystic Altar, then hit Save to Collection.';
UPDATE `quest_template` SET `QuestDescription` = '将神秘附魔保存到你的收藏会为此服务器上的所有角色永久解锁它，让你随时可以从祭坛应用该附魔，而无需卷轴！  将附魔加入你的收藏会摧毁卷轴并消耗一个神秘萃取物。你可以获得的神秘萃取物数量没有限制，所以请务必保存你最喜欢的神秘附魔以及对你构筑至关重要的附魔。  从神秘祭坛的卷轴标签页选择一个神秘卷轴，然后点击保存到收藏。' WHERE `ID` = 580135 AND `QuestDescription` = 'Saving a Mystic Enchant to your collection permanently unlocks it for all characters on this realm, allowing you to apply that enchant from an Altar whenever you want without needing a scroll!  Adding Enchants to your collection destroys the scrolls and consumes a Mystic Extract. There is no limit to how many Mystic Extracts you can acquire, so be sure to save your favorite Mystic Enchants and ones critical to your build.  Select a Mystic Scroll from the Scrolls tab in the Mystic Altar, then hit Save to Collection.';
