UPDATE `quest_template` SET `LogDescription` = '击败一个入侵首领。' WHERE `ID` = 580181 AND `LogDescription` = 'Defeat an Invasion Boss.';
UPDATE `quest_template` SET `QuestDescription` = '入侵是一个周期性的世界事件，会在艾泽拉斯各处生成，并根据附近区域有多少玩家进行缩放。  要找到入侵，你可以查看世界地图，或在世界聊天中询问当前是否有入侵。  要完成入侵，你必须杀死最终首领。进入入侵后，会显示一个完成百分比计数器。一旦该计数器达到 100%，最终首领会出现。' WHERE `ID` = 580181 AND `QuestDescription` = 'An invasion is a periodic World Event that spawns throughout Azeroth that scales to how many players are near the zone.  To find an invasion, you can look on your World Map or ask in World Chat if one is currently up.  To complete an invasion, you must kill the FInal Boss. Once entering an invasion, a percentage completion counter will appear. Once this counter reaches 100% the final boss will appear.';
