UPDATE `quest_template` SET `QuestDescription` = '从神秘祭坛打开附魔收藏标签页，从你的附魔收藏中选择附魔并填满所有空置的激活附魔槽位！如果你无法填满所有 17 个激活附魔槽位，请收集更多相关的神秘附魔。  从你的收藏中激活附魔需要神秘宝珠，可以通过召唤板上的日常任务、地下城和团队副本、战场，或在世界中击败敌人获得！  1 个传说附魔可以应用到祭坛中最大的中央槽位。  3 个史诗附魔可以应用到内环的中型槽位。  你可以在剩余槽位中应用任意数量的稀有和精良附魔。其中许多附魔最多可以叠加 3 次。将鼠标悬停在收藏中的附魔上会显示其最大叠加数。  填满所有 17 个激活附魔槽位！' WHERE `ID` = 580186 AND `QuestDescription` = 'Open the Enchant Collection tab from a Mystic Altar, select Enchants from your Enchant Collections and fill all empty Active Enchant slots! Collect more relevant Mystic Enchants if you cannot fill all 17 Active Enchant slots.  Activating Enchants from your collection requires Mystic Orbs, which can be earned from Daily Quests on the Call Board, Dungeons and Raids, Battlegrounds or defeating enemies in the world!  1 Legendary Enchant can be applied to the large center slot in the Altar.  3 Epic Enchants can be applied in the medium slots in the inner ring.  You can apply as many Rare and Uncommon Enchants in the remaining slots as you''d like. Many of these Enchants can stack up to 3 times. Mousing over the Enchant in the collection reveals its max stack size.  Fill all 17 Active Enchant slots!';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 580186 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：激活一个传说神秘附魔' WHERE `ID` = 580187 AND `LogTitle` = 'Path to Ascension: Activate a Legendary Mystic Enchant';
UPDATE `quest_template` SET `LogDescription` = '激活一个传说神秘附魔。' WHERE `ID` = 580187 AND `LogDescription` = 'Activate a Legendary Mystic Enchant.';
UPDATE `quest_template` SET `QuestDescription` = '从神秘祭坛打开附魔收藏标签页，从你的附魔收藏中选择一个传说附魔并将其应用到中央激活附魔槽位！    从你的收藏中激活附魔需要神秘宝珠，可以通过召唤板上的日常任务、地下城和团队副本、战场，或在世界中击败敌人获得！    你一次只能激活 1 个传说附魔。' WHERE `ID` = 580187 AND `QuestDescription` = 'Open the Enchant Collection tab from a Mystic Altar, select a Legendary Enchant from your Enchant Collections and apply it to the center Active Enchant slot!    Activating Enchants from your collection requires Mystic Orbs, which can be earned from Daily Quests on the Call Board, Dungeons and Raids, Battlegrounds or defeating enemies in the world!    You can only have 1 Legendary Enchant active at a time.';
