UPDATE `quest_template` SET `LogDescription` = '激活 3 个史诗神秘附魔。' WHERE `ID` = 580188 AND `LogDescription` = 'Activate 3 Epic Mystic Enchants.';
UPDATE `quest_template` SET `QuestDescription` = '从神秘祭坛打开附魔收藏标签页，从你的附魔收藏中选择一个史诗附魔并将其应用到 3 个史诗激活附魔槽位之一！    从你的收藏中激活附魔需要神秘宝珠，可以通过召唤板上的日常任务、地下城和团队副本、战场，或在世界中击败敌人获得！    你一次可以激活 3 个不同的史诗附魔。' WHERE `ID` = 580188 AND `QuestDescription` = 'Open the Enchant Collection tab from a Mystic Altar, select an Epic Enchant from your Enchant Collections and apply it to one of the 3 Epic Active Enchant slots!    Activating Enchants from your collection requires Mystic Orbs, which can be earned from Daily Quests on the Call Board, Dungeons and Raids, Battlegrounds or defeating enemies in the world!    You can have 3 different Epic Enchants active at a time.';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 580188 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：神秘附魔专精' WHERE `ID` = 580189 AND `LogTitle` = 'Path to Ascension: Mystic Enchant Specializations';
UPDATE `quest_template` SET `LogDescription` = '- 从角色进阶菜单打开你的附魔收藏，或使用一个祭坛。  - 点击左下角的“更改”按钮以更改你的附魔专精。  - 选择另一个专精然后激活。' WHERE `ID` = 580189 AND `LogDescription` = '- Open your Enchant Collection from the Character Advancement menu or use an Altar.  - Click the ''Change'' button at the bottom left to change your Enchant Specialization.  - Select a different Specialization then Activate.';
UPDATE `quest_template` SET `QuestDescription` = '你以 2 个神秘附魔专精开始。你可以在战斗外随时免费切换你的附魔专精！    使用专精宝典解锁一个新专精也会解锁一个新的附魔专精。使用神秘附魔：专精宝典来解锁更多附魔专精！    神秘附魔专精允许你为激活附魔创建不同的配置。这让你能够：   - 随时切换你的附魔以尝试不同构筑。   - 如果你使用多专精玩不同构筑，可以维护不同的附魔配置。  - 适应特定场景和遭遇。  - 在 PvE 和 PvP 附魔配置之间快速切换。' WHERE `ID` = 580189 AND `QuestDescription` = 'You start with 2 Mystic Enchant Specializations. You can swap your Enchant Specialization anytime outside of combat for free!     Unlocking a new Specialization with a Tome of Specialization will also unlock a new Enchant Specialization. Use Mystic Enchant: Specialization tomes to unlock even more Enchant specs!    Mystic Enchanting Specializations allow you to create different loadouts for your Active Enchants. This allows you to:   - Swap your enchants to try out different builds on the fly.   - Maintain different Enchant loadouts if you use multi-spec to play different builds.  - Adapt to specific scenarios and encounters.  - Quickly switch between PvE and PvP Enchant loadouts.';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 580189 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：世界铸造附魔' WHERE `ID` = 580190 AND `LogTitle` = 'Path to Ascension: Worldforged Enchants';
UPDATE `quest_template` SET `LogDescription` = '将一个世界铸造神秘附魔保存到你的附魔收藏。' WHERE `ID` = 580190 AND `LogDescription` = 'Save a Worldforged Mystic Enchant to your Enchant Collection.';
UPDATE `quest_template` SET `QuestDescription` = '世界铸造神秘附魔无法交易，也无法在祭坛重铸时找到。这些灵魂绑定神秘附魔必须在世界中发现！    获得一个世界铸造神秘附魔卷轴并将其保存到你的收藏。' WHERE `ID` = 580190 AND `QuestDescription` = 'Worldforged Mystic Enchants cannot be traded or found when Reforging at the Altar. These soulbound Mystic Enchants must be discovered in the world!    Acquire a Worldforged Mystic Enchant Scroll and save it to your collection.';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 580190 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：凯旋印记' WHERE `ID` = 580191 AND `LogTitle` = 'Path to Ascension: Mark of Triumph';
UPDATE `quest_template` SET `LogDescription` = '前往暴风城要塞并与 马库斯 交谈' WHERE `ID` = 580191 AND `LogDescription` = 'Travel to Stormwind Keep and speak to Markus';
UPDATE `quest_template` SET `QuestDescription` = '凯旋印记通过完成英雄和史诗难度地下城获得。    这些印记可以兑换装备！用它们升级你的装备，或为对你构筑至关重要的特定装备存起来。    拜访暴风城王座厅的 马库斯 查看你可以获得的装备。' WHERE `ID` = 580191 AND `QuestDescription` = 'Marks of Triumph are earned by completing Heroic and Mythic difficulty dungeons.    These marks can be exchanged for gear! Use them to upgrade your gear or save up for specific equipment key to your build.    Visit Markus in the Stormwind Throne Room to see the gear you can acquire.';
UPDATE `quest_template` SET `QuestCompletionLog` = '与暴风城王座厅的 马库斯 交谈。' WHERE `ID` = 580191 AND `QuestCompletionLog` = 'Talk to Markus in the Stormwind Throne Room.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：凯旋印记' WHERE `ID` = 580192 AND `LogTitle` = 'Path to Ascension: Mark of Triumph';
UPDATE `quest_template` SET `LogDescription` = '前往奥格瑞玛的智慧谷并与 玛尔托格 交谈' WHERE `ID` = 580192 AND `LogDescription` = 'Travel to Orgrimmar''s Valley of Wisdom and speak to Mar''toge';
UPDATE `quest_template` SET `QuestDescription` = '凯旋印记通过完成英雄和史诗难度地下城获得。    这些印记可以兑换装备！用它们升级你的装备，或为对你构筑至关重要的特定装备存起来。    前往奥格瑞玛并与智慧谷王座厅的 玛尔托格 交谈，查看你可以获得的装备。' WHERE `ID` = 580192 AND `QuestDescription` = 'Marks of Triumph are earned by completing Heroic and Mythic difficulty dungeons.    These marks can be exchanged for gear! Use them to upgrade your gear or save up for specific equipment key to your build.    Travel to Orgrimmar and speak with Mar''toge in the Valley of Wisdom throne room to see the gear you can acquire.';
UPDATE `quest_template` SET `QuestCompletionLog` = '拜访奥格瑞玛智慧谷王座厅的 玛尔托格。' WHERE `ID` = 580192 AND `QuestCompletionLog` = 'Visit Mar''toge in Orgrimmar''s Valley of Wisdom throne room.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：完全神秘附魔' WHERE `ID` = 580193 AND `LogTitle` = 'Path to Ascension: Fully Mystic Enchanted';
UPDATE `quest_template` SET `LogDescription` = '在所有 17 个激活附魔槽位中激活一个神秘附魔。' WHERE `ID` = 580193 AND `LogDescription` = 'Activate a Mystic Enchant in all 17 Active Enchant Slots.';
UPDATE `quest_template` SET `QuestDescription` = '从神秘祭坛打开附魔收藏标签页，从你的附魔收藏中选择附魔并填满所有空置的激活附魔槽位！如果你无法填满所有 17 个激活附魔槽位，请收集更多相关的神秘附魔。  从你的收藏中激活附魔需要神秘宝珠，可以通过召唤板上的日常任务、地下城和团队副本、战场，或在世界中击败敌人获得！  外卡 英雄只能使用稀有和精良附魔，且大多数最多可以叠加 3 次！将鼠标悬停在收藏中的附魔上会显示其最大叠加数。  用稀有和精良附魔填满所有 17 个激活附魔槽位！' WHERE `ID` = 580193 AND `QuestDescription` = 'Open the Enchant Collection tab from a Mystic Altar, select Enchants from your Enchant Collections and fill all empty Active Enchant slots! Collect more relevant Mystic Enchants if you cannot fill all 17 Active Enchant slots.  Activating Enchants from your collection requires Mystic Orbs, which can be earned from Daily Quests on the Call Board, Dungeons and Raids, Battlegrounds or defeating enemies in the world!  Wildcard Heroes can only use Rare and Uncommon Enchants and most stack up to 3 times! Mousing over the Enchant in the collection reveals its max stack size.  Fill all 17 Active Enchant slots with Rare and Uncommon Enchants!';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 580193 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路：神秘附魔收藏家' WHERE `ID` = 580194 AND `LogTitle` = 'Path to Ascension: Mystic Enchant Collector';
UPDATE `quest_template` SET `LogDescription` = '将 10 个神秘附魔保存到你的附魔收藏。' WHERE `ID` = 580194 AND `LogDescription` = 'Save 10 Mystic Enchants to your Enchant Collection.';
UPDATE `quest_template` SET `QuestDescription` = '收集神秘附魔并扩展你的附魔收藏会给你更多选择和更多力量。  你可以保存到附魔收藏的神秘附魔数量没有限制。你会继续通过重铸获得神秘萃取物，通过完成各种内容获得，也可以从召唤板旁的 Nozdormu 处以金币或飞升印记购买。  将 10 个神秘附魔保存到你的收藏。' WHERE `ID` = 580194 AND `QuestDescription` = 'Collecting Mystic Enchants and expanding your Enchant Collection will give you more options and more power.  There is no limit to the number of Mystic Enchants you can save to your Enchant Collection. You will continue earning Mystic Extracts from reforging Reforging, earned by completing various content, and can be bought from Nozdormu next to the Call Board for Gold or Marks of Ascension.  Save 10 Mystic Enchants to your collection.';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 580194 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路 外卡：重掷法术' WHERE `ID` = 580195 AND `LogTitle` = 'Path to Ascension Wildcard: Reroll Spells';
UPDATE `quest_template` SET `LogDescription` = '- 与你主城的 塞拉斯·暗月 交谈以获得命运卷轴。  - 使用 N 或从菜单栏打开你的角色进阶菜单。  - 点击你想重掷的技能并选择遗忘。' WHERE `ID` = 580195 AND `LogDescription` = '- Speak to Silas Darkmoon in your Capital City to acquire Scrolls of Fortune.  - Open your Character Advancement menu with N or from the menu bar.  - Click an ability you would like to reroll and select Unlearn.';
UPDATE `quest_template` SET `QuestDescription` = '你在 外卡 中学习的法术和技能可以使用命运卷轴重掷！    塞拉斯·暗月 会每 10 级免费授予你命运卷轴，并在满级时以飞升印记提供命运卷轴。    尝试重掷你最不常用且没有提升你构筑潜力的法术和技能。随着你继续重掷对你帮助最小的法术，你将获得越来越多能显著增强你构筑的法术。' WHERE `ID` = 580195 AND `QuestDescription` = 'The spells and abilities you learn in Wildcard can be rerolled using Scrolls of Fortune!    Silas Darkmoon will grant you free Scrolls of Fortune every 10 levels and offers Scrolls of Fortune at max level for Marks of Ascension.    Try to Reroll your least used spells and abilities that are not increasing your build''s potential. As you continue rerolling the spells that help you the least, you will acquire more and more spells that significantly empower your build.';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 580195 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路 外卡：重掷天赋' WHERE `ID` = 580196 AND `LogTitle` = 'Path to Ascension Wildcard: Reroll Talents';
UPDATE `quest_template` SET `LogDescription` = '- 与你主城的 塞拉斯·暗月 交谈以获得命运卷轴。  - 使用 N 或从菜单栏打开你的角色进阶菜单。  - 点击你想重掷的天赋并选择遗忘。' WHERE `ID` = 580196 AND `LogDescription` = '- Speak to Silas Darkmoon in your Capital City to acquire Scrolls of Fortune.  - Open your Character Advancement menu with N or from the menu bar.  - Click a Talent you would like to reroll and select Unlearn.';
UPDATE `quest_template` SET `QuestDescription` = '你在 外卡 中学习的天赋可以使用命运卷轴：天赋和命运卷轴重掷！    塞拉斯·暗月 会每 10 级免费授予你命运卷轴，并在满级时以飞升印记提供命运卷轴。    尝试重掷不直接提升你力量或增强你首先使用的技能的天赋！随着你重掷你最弱或最不相关的天赋，你的构筑会迅速充满全部增添巨大力量的天赋。' WHERE `ID` = 580196 AND `QuestDescription` = 'The Talents you learn in Wildcard can be rerolled using Scrolls of Fortune: Talents and Scrolls of Fortune!    Silas Darkmoon will grant you free Scrolls of Fortune every 10 levels and offers Scrolls of Fortune at max level for Marks of Ascension.    Try to Reroll talents that do not directly increase your power or empower abilities you use first! As you reroll your weakest or least relevant talents, your build will quickly fill up with talents that all add immense power.';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 580196 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路 外卡：锁定法术和天赋' WHERE `ID` = 580197 AND `LogTitle` = 'Path to Ascension Wildcard: Locking Spells and Talents';
UPDATE `quest_template` SET `LogDescription` = '- 打开角色进阶菜单  - 在你想锁定的技能或天赋上选择锁定图标' WHERE `ID` = 580197 AND `LogDescription` = '- Open the Character Advancement Menu  - Select the Lock icon on an ability or talent you would like to lock';
UPDATE `quest_template` SET `QuestDescription` = '你可以锁定不想意外遗忘或重掷的法术和天赋！这些可以随时解锁。    锁定的法术和天赋也会排序到顶部。这让你可以快速找到要重掷的法术和天赋，并确保你不会重掷尚未准备好的！    锁定系统既保护你的构筑，又让重掷更容易。' WHERE `ID` = 580197 AND `QuestDescription` = 'You can lock Spells and Talents you don''t want to accidentally unlearn or reroll! These can be unlocked at any time.    Locked Spells and Talents also sort to the top. This allows you to quickly find spells and talents to reroll and ensures you don''t reroll ones you are not ready to!    The locking system both protects your build and makes rerolling easier.';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 580197 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路 外卡：技能卡包' WHERE `ID` = 580198 AND `LogTitle` = 'Path to Ascension Wildcard: Skill Card Packs';
UPDATE `quest_template` SET `LogDescription` = '- 拜访主城的 塞拉斯·暗月 - 完成满级命运卷轴任务以赚取密封卡包。 - 使用你的密封卡包打开它。' WHERE `ID` = 580198 AND `LogDescription` = '- Visit Silas Darkmoon in a Capital City - Complete max level Scroll of Fortune quests to earn Sealed Card Packs. - Use your Sealed Card Pack to open it.';
UPDATE `quest_template` SET `QuestDescription` = '密封卡包含有满级天赋技能卡。  打开这些卡包以收集技能卡，你可以用它们来更好地控制未来的构筑，或保证当前构筑中的天赋。  从卡包中揭示的卡牌会自动加入你账号通用的技能卡收藏。' WHERE `ID` = 580198 AND `QuestDescription` = 'Sealed Card Packs contain max-level Talent Skill Cards.  Open these packs to collect Skill Cards you can use to gain more control of future builds or guarantee talents in your current one.  Cards revealed from packs are automatically added to your account-wide Skill Card Collection.';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 580198 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路 外卡：金色技能卡' WHERE `ID` = 580199 AND `LogTitle` = 'Path to Ascension Wildcard: Golden Skill Cards';
UPDATE `quest_template` SET `LogDescription` = '- 拜访主城的 塞拉斯·暗月  - 选择金色技能卡菜单并购买一个金色卡包  - 使用你的金色密封卡包打开它。' WHERE `ID` = 580199 AND `LogDescription` = '- Visit Silas Darkmoon in a Capital City  - Select Golden Skill Cards Menu and buy a Golden Pack  - Use your Golden Sealed Card Pack to open it.';
UPDATE `quest_template` SET `QuestDescription` = '金色密封卡包含有金色技能卡！    金色技能卡包和金色卡牌的功能与普通技能卡相同，但它们可以填充金色技能卡槽位，让你在开始收集这些卡牌时对构筑有更多控制。    当你打开普通技能卡包时，随着你的重复卡牌被转化为免费卡包的进度，这些卡包也会定期获得。' WHERE `ID` = 580199 AND `QuestDescription` = 'Golden Sealed Card Packs contain Golden Skill Cards!    Golden Skill Cards Packs and Golden Cards function the same as normal Skill Cards, but they can fill the Golden Skill Card slots, allowing even more control of your build as you begin collecting these cards.    These packs are also acquired periodically when opening Normal Skill Card packs as your duplicate cards are transformed into progress towards free card packs.';
UPDATE `quest_template` SET `QuestCompletionLog` = '返回召唤板。' WHERE `ID` = 580199 AND `QuestCompletionLog` = 'Return to the Call Board.';
UPDATE `quest_template` SET `LogTitle` = '飞升之路 外卡：激活技能卡' WHERE `ID` = 580201 AND `LogTitle` = 'Path to Ascension Wildcard: Activate a Skill Card';
UPDATE `quest_template` SET `LogDescription` = '- 打开角色进阶 - 点击技能卡标签页 - 在你 1-9 级时激活一个技能卡。' WHERE `ID` = 580201 AND `LogDescription` = '- Open Character Advancement - Click the Skill Cards tab - Activate a Skill Card while you are level 1-9.';
UPDATE `quest_template` SET `QuestDescription` = '激活技能卡保证你会掷出那个法术或天赋。  技能卡只能在你 1-9 级时激活。你可以随时将技能卡加入你的收藏，且你的技能卡收藏在你账号上的所有角色之间共享。新角色和转生角色可以使用你已收集的卡牌。  如果你使用多个专精，你可以在一个专精中使用技能卡，直到该专精掷出它的第 5 个法术。' WHERE `ID` = 580201 AND `QuestDescription` = 'Activating Skill Cards guarantees that you will roll that Spell or Talent.  Skill Cards can only be activated while you are levels 1-9. You can add Skill Cards to your collection at any time, and your Skill Card Collection is shared across all characters on your account. New characters and Prestiged characters can use cards you have already collected.  If you use multiple specializations, you can use Skill Cards in a specialization until that specialization rolls its 5th spell.';
